import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007L;
    static int K_val;
    static long N_val;
    static MatrixType identityMat = new MatrixType();
    static MatrixType[] matricesArr = new MatrixType[70];
    static MatrixType finalMat = new MatrixType();
    static MatrixType[] prefixArr = new MatrixType[70];
    static MatrixType[] suffixArr = new MatrixType[70];

    static class MatrixType {
        int[][] data = new int[33][33];
    }

    static void printMat(final MatrixType mat) {
        for (int i = 0; i <= K_val; i++) {
            for (int j = 0; j <= K_val; j++)
                System.out.print(mat.data[i][j] + " ");
            System.out.println();
        }
        System.out.println();
    }

    static MatrixType multiplyMatrices(final MatrixType A, final MatrixType B) {
        MatrixType C = new MatrixType();
        // Initialize C as identity matrix
        for (int i = 0; i <= K_val; i++) {
            for (int j = 0; j <= K_val; j++) {
                C.data[i][j] = 0;
            }
        }
        for (int i = 0; i <= K_val; i++) {
            C.data[i][i] = 1;
        }
        for (int k = 0; k <= K_val; k++) {
            for (int i = 0; i <= K_val; i++) {
                for (int j = 0; j <= K_val; j++) {
                    long val = ((long) A.data[i][k] * B.data[k][j]) % MOD;
                    C.data[i][j] = (int) ((C.data[i][j] + val) % MOD);
                }
            }
        }
        return C;
    }

    static void computePrefixSuffixMatrices() {
        int i;
        prefixArr[0] = matricesArr[0];
        for (i = 1; i < K_val; i++)
            prefixArr[i] = multiplyMatrices(prefixArr[i - 1], matricesArr[i]);
        suffixArr[K_val - 1] = matricesArr[K_val - 1];
        for (i = K_val - 2; i >= 0; i--)
            suffixArr[i] = multiplyMatrices(matricesArr[i], suffixArr[i + 1]);
        matricesArr[0] = suffixArr[0];
        for (i = 1; i < K_val; i++)
            matricesArr[i] = multiplyMatrices(suffixArr[i], prefixArr[i - 1]);
    }

    static void run() {
        Scanner sc = new Scanner(System.in);
        N_val = sc.nextLong();
        K_val = sc.nextInt();

        // Initialize identity matrix
        for (int i = 0; i <= K_val; i++) {
            identityMat.data[i][i] = 1;
        }

        finalMat = new MatrixType();
        // Initialize finalMat as identity
        for (int i = 0; i <= K_val; i++) {
            for (int j = 0; j <= K_val; j++) {
                finalMat.data[i][j] = 0;
            }
        }
        for (int i = 0; i < K_val; i++) {
            matricesArr[i] = new MatrixType();
            for (int j = 0; j <= K_val; j++) {
                matricesArr[i].data[j][j] = 1;
                matricesArr[i].data[j][i] = 1;
            }
            finalMat.data[i][i] = 1;
        }
        finalMat.data[K_val][K_val] = 1;

        while (N_val > 0) {
            long r = N_val % K_val;
            if (r != 0) {
                long pos = 0, tmp = N_val;
                while (tmp != 0) {
                    tmp /= K_val;
                    pos = (pos + tmp) % K_val;
                }
                for (int i = (int) r - 1; i >= 0; i--) {
                    finalMat = multiplyMatrices(matricesArr[(int) ((pos + i) % K_val)], finalMat);
                }
            }
            computePrefixSuffixMatrices();
            N_val /= K_val;
        }
        int answer = 1;
        for (int i = 0; i < K_val; i++)
            answer = (answer + finalMat.data[K_val][i]) % (int) MOD;
        System.out.println(answer);
        sc.close();
    }

    public static void main(String[] args) {
        run();
    }
}

